from datetime import date

from rest_framework import serializers

from .models import Patient

SEX_CHOICES = ("male", "female", "other")
MIN_BIRTH_YEAR = 1900
MAX_WEIGHT_KG = 500


class PatientSerializer(serializers.ModelSerializer):
    sex = serializers.ChoiceField(choices=SEX_CHOICES, required=False, allow_blank=True)

    class Meta:
        model = Patient
        fields = ["id", "patient_code", "birth_year", "sex", "weight_kg", "created_at"]
        # `owner` is not exposed at all; `patient_code` is generated by the server.
        read_only_fields = ["id", "patient_code", "created_at"]

    def validate_birth_year(self, value):
        if value is None:
            return value
        if not MIN_BIRTH_YEAR <= value <= date.today().year:
            raise serializers.ValidationError(f"Birth year must be between {MIN_BIRTH_YEAR} and {date.today().year}.")
        return value

    def validate_weight_kg(self, value):
        if value is None:
            return value
        if not 0 < value <= MAX_WEIGHT_KG:
            raise serializers.ValidationError(f"Weight must be greater than 0 and at most {MAX_WEIGHT_KG} kg.")
        return value